const body = $json.body ?? $json;
return [{
  json: {
    user_id: body.user_id ?? null,
    session_id: body.session_id ?? null,
    message_text: body.message_text ?? body.message ?? '',
    building_id: body.building_id ?? null,
    study_id: body.study_id ?? null,
    debug_mode: body.debug_mode ?? false,
    source: 'website_dashboard',
    received_at: new Date().toISOString(),
  }
}];

return [{
  json: {
    assistant_response_text: $json.assistant_response_text ?? 'I could not complete that request safely.',
    action_type: $json.action_type ?? 'clarify_request',
    study_id: $json.study_id ?? null,
    study_readiness_status: $json.study_readiness_status ?? null,
    setup_request: $json.setup_request ?? null,
    dashboard_payload: $json,
  }
}];
